 namespace Pterodactyl\Services\Dezerx\Billing; use Pterodactyl\Services\Dezerx\Settings; class Billing { public const KEY = 'billing'; public const PAYMENTER = 'paymenter'; public const WHMCS = 'whmcs'; public const DEZERX = 'dezerx'; public const PROVIDERS = [self::PAYMENTER, self::WHMCS, self::DEZERX]; public const DEFAULT_WARN_DAYS = 7; public const PREVIEWS = ['', 'due', 'overdue']; public static function all(): array { $stored = Settings::get(self::KEY) ?? []; $provider = strtolower(trim((string) ($stored['provider'] ?? self::PAYMENTER))); return [ 'enabled' => (bool) ($stored['enabled'] ?? false), 'provider' => in_array($provider, self::PROVIDERS, true) ? $provider : self::PAYMENTER, 'endpoint' => rtrim(trim((string) ($stored['endpoint'] ?? '')), '/'), 'identifier' => trim((string) ($stored['identifier'] ?? '')), 'secret' => trim((string) ($stored['secret'] ?? '')), 'currency' => trim((string) ($stored['currency'] ?? '')), 'warn_days' => max(0, min(120, (int) ($stored['warn_days'] ?? self::DEFAULT_WARN_DAYS))), 'warn_text' => trim((string) ($stored['warn_text'] ?? '')), 'overdue_text' => trim((string) ($stored['overdue_text'] ?? '')), 'warn_body' => trim((string) ($stored['warn_body'] ?? '')), 'overdue_body' => trim((string) ($stored['overdue_body'] ?? '')), 'global' => (bool) ($stored['global'] ?? false), 'preview' => self::preview($stored['preview'] ?? null), ]; } public static function save(array $values): void { $current = self::all(); $provider = strtolower(trim((string) ($values['provider'] ?? $current['provider']))); $secret = trim((string) ($values['secret'] ?? '')); Settings::put(self::KEY, [ 'enabled' => (bool) ($values['enabled'] ?? false), 'provider' => in_array($provider, self::PROVIDERS, true) ? $provider : self::PAYMENTER, 'endpoint' => rtrim(trim((string) ($values['endpoint'] ?? '')), '/'), 'identifier' => trim((string) ($values['identifier'] ?? '')), 'secret' => $secret === '' ? $current['secret'] : $secret, 'currency' => mb_substr(trim((stri